from fractions import Fraction

def one_step_drift(f, s, n, p):
    """E[f(s + X, n + 1)] - f(s, n), exactly, where the step X
    is +1 with chance p and -1 otherwise."""
    p = Fraction(p)
    return p * f(s + 1, n + 1) + (1 - p) * f(s - 1, n + 1) - f(s, n)

def is_walk_martingale(f, p, s_values, n_values):
    """True when the drift is 0 at every s and n given."""
    return all(one_step_drift(f, s, n, p) == 0 for s in s_values for n in n_values)
